using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Security.Cryptography;using Autodesk.Revit.DB;using Autodesk.Revit.UI;
namespace Autodesk.Revit.DB {
 public class ElementId {public long Value;public ElementId(long v){Value=v;}} public class View {public Document Document;public ElementId Id;public bool IsValidObject=true,IsTemplate;}
 public enum IFCVersion {IFC4} public enum TransactionStatus {Started,RolledBack,Error}
 public class IFCExportOptions:IDisposable {public IFCVersion FileVersion;public ElementId FilterViewId;public bool ExportBaseQuantities,WallAndColumnSplitting;public int SpaceBoundaryLevel;public void Dispose(){}}
 public static class OptionalFunctionalityUtils {public static bool Available=true;public static bool IsIFCAvailable(){return Available;}}
 public class Transaction:IDisposable {Document d;public Transaction(Document d,string n){this.d=d;}public TransactionStatus Start(){return TransactionStatus.Started;}public TransactionStatus RollBack(){return d.RollbackFail?TransactionStatus.Error:TransactionStatus.RolledBack;}public void Dispose(){}}
 public class Document {public bool IsFamilyDocument,Fail,Extra,RollbackFail;public int Calls;public View View;public object GetElement(ElementId id){return View;}public bool Export(string dir,string name,IFCExportOptions o){Calls++;if(name!="model.ifc"||o.FileVersion!=IFCVersion.IFC4||o.FilterViewId!=View.Id||o.ExportBaseQuantities||o.WallAndColumnSplitting||o.SpaceBoundaryLevel!=0)throw new Exception("options");File.WriteAllText(Path.Combine(dir,name),"ifc");if(Extra)File.WriteAllText(Path.Combine(dir,"extra"),"x");if(Fail)throw new IOException();return true;}}
}
namespace Autodesk.Revit.UI {public class UIDocument {public Document Document;}public class UIApplication {public UIDocument ActiveUIDocument;}}
namespace RevitLocalCodex {
 internal interface IUnregisteredDwgStageLease { string StageId {get;} string DirectoryPath {get;} IList<DwgStageFileFact> Snapshot(); }
 internal class DwgStageFileFact { internal string Name,Identity,Sha256; internal long Bytes; internal bool Regular; }
 class FakeLease:IUnregisteredDwgStageLease {public string StageId{get;private set;}public string DirectoryPath{get;private set;}public bool Broken;public FakeLease(string root){StageId=Guid.NewGuid().ToString("D");DirectoryPath=Path.Combine(root,StageId);Directory.CreateDirectory(DirectoryPath);}public IList<DwgStageFileFact> Snapshot(){if(Broken)throw new IOException();return Directory.GetFiles(DirectoryPath).Select(p=>new DwgStageFileFact{Name=Path.GetFileName(p),Regular=true,Identity="mock",Bytes=new FileInfo(p).Length,Sha256=new string('a',64)}).ToArray();}}
 class Journal:IIfcOriginalRequestJournal {public bool Started,Observed;public void RecordStarted(string id,string stage,long view){if(Started)throw new InvalidOperationException("no replay");Started=true;}public void RecordObserved(IfcPrototypeReceipt r){Observed=true;}}
 class Test {static int n;static void C(bool v){if(!v)throw new Exception("test "+n);n++;}static void Main(string[] a){string root=a[0];Directory.CreateDirectory(root);var d=new Document{View=new View{Id=new ElementId(1)}};d.View.Document=d;var ui=new UIApplication{ActiveUIDocument=new UIDocument{Document=d}};string id=Guid.NewGuid().ToString("D");var l=new FakeLease(root);var j=new Journal();OptionalFunctionalityUtils.Available=false;try{UnregisteredIfcStagePrototype.Run(ui,1,id,l,j);throw new Exception();}catch(InvalidOperationException){C(!j.Started&&d.Calls==0);}OptionalFunctionalityUtils.Available=true;var r=UnregisteredIfcStagePrototype.Run(ui,1,id,l,j);C(j.Started&&j.Observed&&r.ExpectedSingleIfc&&!r.PublicationAuthorized&&r.TransactionState=="rolled_back");try{UnregisteredIfcStagePrototype.Run(ui,1,id,l,j);throw new Exception();}catch(InvalidOperationException){C(d.Calls==1);}d.Fail=true;l=new FakeLease(root);j=new Journal();r=UnregisteredIfcStagePrototype.Run(ui,1,id,l,j);C(r.Outcome=="exporter_threw"&&File.Exists(Path.Combine(l.DirectoryPath,"model.ifc")));d.Fail=false;d.Extra=true;l=new FakeLease(root);j=new Journal();r=UnregisteredIfcStagePrototype.Run(ui,1,id,l,j);C(!r.ExpectedSingleIfc&&r.ObservedFiles.Length==2&&!r.PublicationAuthorized);d.Extra=false;d.RollbackFail=true;l=new FakeLease(root);j=new Journal();r=UnregisteredIfcStagePrototype.Run(ui,1,id,l,j);C(r.TransactionState=="unknown"&&!r.PublicationAuthorized);l=new FakeLease(root){Broken=true};j=new Journal();try{UnregisteredIfcStagePrototype.Run(ui,1,id,l,j);throw new Exception();}catch(IOException){C(j.Started&&!j.Observed&&File.Exists(Path.Combine(l.DirectoryPath,"model.ifc")));}Console.WriteLine("PASS "+n);}}
}
